(function () {
    var ua = navigator.userAgent.toLowerCase();
    var isQQ = /qq\//.test(ua);
    var isWeChat = /micromessenger/.test(ua);
    if (!(isQQ || isWeChat)) return;

    var $body = document.body;
    $body.style.padding = 0;
    $body.style.margin = 0;

    var overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100vh;z-index:999999;'
        + 'background:rgba(0,0,0,.85);display:flex;flex-direction:column;align-items:center;justify-content:center;'
        + 'text-align:center;color:#fff;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif;';

    overlay.innerHTML = ''
        + '<div style="font-size:24px;font-weight:700;letter-spacing:2px;">请在浏览器中打开</div>'
        + '<div style="margin-top:18px;font-size:15px;line-height:2;">点击右上角 "···" 菜单<br>选择 "在浏览器中打开"<br>以获得更好的体验</div>'
        + '<button id="anti-redness-copy" style="margin-top:30px;padding:11px 40px;border:none;border-radius:8px;background:#fff;color:#111;font-size:15px;font-weight:600;cursor:pointer;">复制链接</button>';

    $body.appendChild(overlay);

    overlay.querySelector('#anti-redness-copy').addEventListener('click', function () {
        var btn = this, url = location.href;
        function done() {
            btn.textContent = '已复制';
            setTimeout(function () { btn.textContent = '复制链接'; }, 1500);
        }
        function fallback() {
            var ta = document.createElement('textarea');
            ta.value = url;
            ta.style.cssText = 'position:fixed;top:-999px;opacity:0;';
            document.body.appendChild(ta);
            ta.focus(); ta.select();
            var ok = false;
            try { ok = document.execCommand('copy'); } catch (e) {}
            document.body.removeChild(ta);
            btn.textContent = ok ? '已复制' : '复制失败';
            setTimeout(function () { btn.textContent = '复制链接'; }, 1500);
        }
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(url).then(done).catch(fallback);
        } else {
            fallback();
        }
    });
})();
